<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import UiButton from '@/components/ui/UiButton.vue'
import UiNotice from '@/components/ui/UiNotice.vue'
import OwnerField from '@/components/owner/OwnerField.vue'
import { eventPayload, localEventTime, useOwnerApi } from '@/composables/useOwnerApi'
import { useAuthStore } from '@/stores/auth'
import { toApiError } from '@/lib/api'
import { inputTime, positiveMoney } from '@/lib/billing'
import { formatMoney } from '@/lib/format'
import { formatDateTime } from '@/lib/notifications'
import type { Invoice, Payment, PaymentPayload } from '@/types/billing'
const props = defineProps<{ invoice: Invoice }>()
const emit = defineEmits<{ close: []; paid: [invoice: Invoice, payment: Payment, replayed: boolean] }>()
const client = useOwnerApi(), auth = useAuthStore(), initialUser = auth.user?.id
const storageKey = `rental:pending-payment:${initialUser}:${props.invoice.id}`
const form = ref({ amount: props.invoice.outstanding_amount, paid_at: localEventTime(), payment_method: 'cash' as 'cash' | 'bank_transfer' })
const pending = ref<PaymentPayload | null>(null), reviewing = ref(false), uncertain = ref(false), storageError = ref('')
try { const saved = sessionStorage.getItem(storageKey); if (saved) { const value: unknown = JSON.parse(saved); if (value && typeof value === 'object' && 'amount' in value && 'paid_at' in value && 'payment_method' in value && 'idempotency_key' in value) { const candidate = value as PaymentPayload; if (typeof candidate.amount === 'string' && positiveMoney(candidate.amount) && typeof candidate.paid_at === 'string' && /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(candidate.paid_at) && ['cash', 'bank_transfer'].includes(candidate.payment_method) && typeof candidate.idempotency_key === 'string' && /^[a-zA-Z0-9][a-zA-Z0-9._:-]{7,63}$/.test(candidate.idempotency_key)) { pending.value = candidate; form.value = { amount: candidate.amount, paid_at: inputTime(candidate.paid_at), payment_method: candidate.payment_method }; reviewing.value = true; uncertain.value = true } } } } catch { storageError.value = 'Trình duyệt chưa lưu được yêu cầu đang chờ. Giữ hộp thoại mở nếu mất kết nối để gửi lại an toàn.' }
const payload = computed(() => pending.value ?? { amount: form.value.amount, paid_at: eventPayload(form.value.paid_at), payment_method: form.value.payment_method, idempotency_key: '' })
function clearPending() { pending.value = null; uncertain.value = false; try { sessionStorage.removeItem(storageKey) } catch { /* In-memory payload still cleared. */ } }
watch(() => auth.user?.id, id => { if (id !== initialUser) { pending.value = null; uncertain.value = false; emit('close') } }, { flush: 'sync' })
async function pay() { if (!reviewing.value || client.busy.value) return; if (!pending.value) { pending.value = { amount: form.value.amount, paid_at: eventPayload(form.value.paid_at), payment_method: form.value.payment_method, idempotency_key: crypto.randomUUID() }; try { sessionStorage.setItem(storageKey, JSON.stringify(pending.value)) } catch { storageError.value = 'Không lưu được yêu cầu đang chờ trong trình duyệt. Giữ hộp thoại mở nếu mất kết nối.' } }
  const wasUncertain = uncertain.value
  try { const result = await client.write<{ data: Payment; invoice: Invoice; replayed: boolean }>('post', `/invoices/${props.invoice.id}/payments`, { ...pending.value }); clearPending(); emit('paid', result.invoice, result.data, result.replayed); emit('close') } catch (caught) { const error = toApiError(caught); if (wasUncertain || error.status === 0 || error.status >= 500 || error.status === 408) { if (auth.user?.id === initialUser) uncertain.value = true } else { clearPending(); reviewing.value = false } }
}
</script>
<template><UiDialog open title="Ghi nhận tiền đã thu" description="Chỉ xác nhận khi bạn đã thực nhận tiền mặt hoặc chuyển khoản." @update:open="value => { if (!value && !client.busy.value) emit('close') }"><UiNotice v-if="uncertain" tone="warning" title="Lần thu đang chờ xác nhận">Yêu cầu trước có thể đã được ghi nhận. Giữ nguyên thông tin và bấm “Gửi lại lần thu đang chờ” để kiểm tra; hệ thống không cộng thêm lần thu này.</UiNotice><UiNotice v-if="storageError" tone="warning">{{ storageError }}</UiNotice><p v-if="client.error.value" class="form-error" role="alert">{{ client.error.value }}</p><dl class="record-facts"><div><dt>Hóa đơn</dt><dd>{{ invoice.invoice_number }}</dd></div><div><dt>Còn phải thu hiện tại</dt><dd><strong>{{ formatMoney(invoice.outstanding_amount) }}</strong></dd></div></dl><form v-if="!reviewing" class="form-grid" @submit.prevent="reviewing = true"><OwnerField v-model="form.amount" label="Số tiền thực nhận" name="amount" type="number" min="0.01" step="0.01" required :errors="client.errors.value" /><UiButton variant="ghost" @click="form.amount = invoice.outstanding_amount">Điền toàn bộ còn nợ</UiButton><OwnerField v-model="form.paid_at" label="Thời điểm nhận tiền (giờ Việt Nam)" name="paid_at" type="datetime-local" step="1" required :errors="client.errors.value" /><label class="select-field">Hình thức nhận tiền<select v-model="form.payment_method" class="ui-select"><option value="cash">Tiền mặt</option><option value="bank_transfer">Chuyển khoản</option></select></label><UiButton type="submit">Xem lại lần thu</UiButton></form><template v-else><div class="review-box"><h3>Xem lại tiền thực nhận</h3><p><strong>{{ formatMoney(payload.amount) }}</strong> · {{ payload.payment_method === 'cash' ? 'Tiền mặt' : 'Chuyển khoản' }}</p><p>{{ formatDateTime(payload.paid_at) }}</p><p>Lần thu đã xác nhận được lưu vào lịch sử. Hãy kiểm tra kỹ số tiền và thời điểm.</p></div><div class="button-row"><UiButton v-if="!pending" variant="secondary" :disabled="client.busy.value" @click="reviewing = false">Quay lại sửa</UiButton><UiButton :loading="client.busy.value" @click="pay">{{ uncertain ? 'Gửi lại lần thu đang chờ' : 'Xác nhận đã nhận tiền' }}</UiButton></div></template></UiDialog></template>
